content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --bg-main: #f8fafc;
  --bg-card: #ffffff;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* アプリ全体のコンテナ */
.app-container {
  max-width: 1040px;
  margin: 0 auto;
  padding: 32px 20px 48px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダーエリア */
.app-header {
  text-align: center;
  padding: 12px 0 8px;
}

.app-title {
  font-size: 26px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 14px;
  color: var(--text-muted);
}

/* 検索・絞り込みパネル */
.search-panel {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.search-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 16px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 220px;
}

.input-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
}

.search-input,
.select-input {
  width: 100%;
  padding: 10px 14px;
  font-size: 14px;
  color: var(--text-main);
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  font-family: inherit;
}

.search-input::placeholder {
  color: var(--text-light);
}

.search-input:focus,
.select-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.18);
}

.select-input {
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2364748b' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 12px center;
  background-size: 16px;
  padding-right: 36px;
}

.reset-btn {
  padding: 10px 18px;
  font-size: 14px;
  font-weight: 500;
  color: #475569;
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 42px;
}

.reset-btn:hover {
  background-color: #e2e8f0;
  color: #1e293b;
}

.reset-btn:active {
  transform: translateY(1px);
}

/* 検索結果カウントバッジ */
.result-count {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: var(--text-muted);
  border-top: 1px dashed var(--border-color);
  padding-top: 12px;
}

.count-badge {
  display: inline-flex;
  align-items: center;
  background-color: var(--primary-light);
  color: var(--primary-hover);
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 13px;
}

/* テーブルカードエリア */
.table-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* 社員テーブル基本 */
.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 14px;
}

.employee-table th {
  background-color: #f8fafc;
  color: #475569;
  font-weight: 600;
  padding: 14px 18px;
  border-bottom: 2px solid var(--border-color);
  white-space: nowrap;
  user-select: none;
}

.employee-table td {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  vertical-align: middle;
  color: var(--text-main);
}

.employee-table tbody tr {
  transition: background-color 0.15s ease;
}

.employee-table tbody tr:hover {
  background-color: #f8fafc;
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

/* ソート可能見出し */
.th-sortable {
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.th-sortable:hover {
  background-color: #f1f5f9;
  color: var(--primary-hover);
}

.th-active {
  background-color: #eff6ff;
  color: var(--primary-hover);
}

.sort-indicator {
  display: inline-block;
  margin-left: 6px;
  font-size: 11px;
  color: var(--primary-hover);
  transition: transform 0.15s ease;
}

/* 各セルスタイル */
.td-age {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.td-dept {
  white-space: nowrap;
}

/* 部署バッジタグ */
.dept-tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

/* 営業部 */
.dept-sales {
  background-color: #fff7ed;
  color: #c2410c;
  border: 1px solid #ffedd5;
}

/* 開発部 */
.dept-dev {
  background-color: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #dbeafe;
}

/* 人事部 */
.dept-hr {
  background-color: #fdf2f8;
  color: #be185d;
  border: 1px solid #fce7f3;
}

/* 企画部 */
.dept-planning {
  background-color: #ecfdf5;
  color: #047857;
  border: 1px solid #d1fae5;
}

/* 総務部 */
.dept-general {
  background-color: #f5f3ff;
  color: #6d28d9;
  border: 1px solid #ede9fe;
}

/* データゼロ件メッセージ */
.no-data-msg {
  text-align: center;
  padding: 48px 24px;
  color: var(--text-muted);
  font-size: 14px;
}

/* フッター */
.app-footer {
  margin-top: auto;
  text-align: center;
  font-size: 12px;
  color: var(--text-light);
  padding: 16px 0;
}

/* レスポンシブ調整（スマホ対応） */
@media (max-width: 640px) {
  .app-container {
    padding: 20px 12px 36px;
    gap: 16px;
  }

  .app-title {
    font-size: 20px;
  }

  .search-panel {
    padding: 16px;
  }

  .search-row {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .input-group {
    flex: 1 1 100%;
  }

  .reset-btn {
    width: 100%;
  }

  .employee-table th,
  .employee-table td {
    padding: 10px 12px;
    font-size: 13px;
  }
}

export interface Employee {
  id: number;
  name: string;
  kana: string;
  department: string;
  age: number;
  role: string;
}

export type SortKey = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

export interface SearchBarProps {
  searchQuery: string;
  onSearchChange: (val: string) => void;
  departmentFilter: string;
  onDepartmentChange: (val: string) => void;
  departments: string[];
  onReset: () => void;
  totalCount: number;
  matchCount: number;
}

export interface EmployeeTableProps {
  employees: Employee[];
  sortKey: SortKey;
  sortOrder: SortOrder;
  onSort: (key: SortKey) => void;
}

import { ChangeEvent } from 'react';
import { SearchBarProps } from '../types';

const SearchBar = ({
  searchQuery = '',
  onSearchChange,
  departmentFilter = '',
  onDepartmentChange,
  departments = [],
  onReset,
  totalCount = 0,
  matchCount = 0,
}: SearchBarProps) => {
  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSearchChange?.(e.target.value);
  };

  const handleSelectChange = (e: ChangeEvent<HTMLSelectElement>) => {
    onDepartmentChange?.(e.target.value);
  };

  const handleResetClick = () => {
    onReset?.();
  };

  return (
    <div className="search-panel">
      <div className="search-row">
        <div className="input-group">
          <label htmlFor="search-input-field" className="input-label">
            社員名・フリガナ検索
          </label>
          <input
            id="search-input-field"
            type="text"
            className="search-input"
            placeholder="例: 佐藤、サトウ"
            value={searchQuery}
            onChange={handleInputChange}
          />
        </div>

        <div className="input-group">
          <label htmlFor="department-select-field" className="input-label">
            部署絞り込み
          </label>
          <select
            id="department-select-field"
            className="select-input"
            value={departmentFilter}
            onChange={handleSelectChange}
          >
            <option value="">すべての部署</option>
            {departments.map((dept) => (
              <option key={dept} value={dept}>
                {dept}
              </option>
            ))}
          </select>
        </div>

        <button
          type="button"
          className="reset-btn"
          onClick={handleResetClick}
        >
          条件をリセット
        </button>
      </div>

      <div className="result-count">
        <span>表示中の社員</span>
        <span className="count-badge">
          {matchCount}件 / 全{totalCount}人
        </span>
      </div>
    </div>
  );
};

export default SearchBar;

import { EmployeeTableProps, SortKey } from '../types';

const getDepartmentClass = (dept: string): string => {
  switch (dept) {
    case '営業部':
      return 'dept-tag dept-sales';
    case '開発部':
      return 'dept-tag dept-dev';
    case '人事部':
      return 'dept-tag dept-hr';
    case '企画部':
      return 'dept-tag dept-planning';
    case '総務部':
      return 'dept-tag dept-general';
    default:
      return 'dept-tag';
  }
};

const EmployeeTable = ({
  employees = [],
  sortKey,
  sortOrder,
  onSort,
}: EmployeeTableProps) => {
  const handleSortClick = (key: SortKey) => {
    onSort?.(key);
  };

  const renderSortIndicator = (key: SortKey) => {
    if (sortKey !== key) {
      return null;
    }
    return (
      <span className="sort-indicator">
        {sortOrder === 'asc' ? '▲' : '▼'}
      </span>
    );
  };

  const getThClass = (key: SortKey) => {
    return sortKey === key ? 'th-sortable th-active' : 'th-sortable';
  };

  return (
    <div className="table-card">
      <div className="table-wrapper">
        <table className="employee-table">
          <thead>
            <tr>
              <th
                className={getThClass('name')}
                onClick={() => handleSortClick('name')}
              >
                氏名 {renderSortIndicator('name')}
              </th>
              <th
                className={getThClass('department')}
                onClick={() => handleSortClick('department')}
              >
                部署 {renderSortIndicator('department')}
              </th>
              <th
                className={getThClass('age')}
                onClick={() => handleSortClick('age')}
              >
                年齢 {renderSortIndicator('age')}
              </th>
              <th>役職</th>
            </tr>
          </thead>
          <tbody>
            {employees.length === 0 ? (
              <tr>
                <td colSpan={4} className="no-data-msg">
                  該当する社員は見つかりませんでした。条件を変えて再検索してください。
                </td>
              </tr>
            ) : (
              employees.map((emp) => (
                <tr key={emp.id}>
                  <td>
                    <strong>{emp.name}</strong>
                    <div style={{ fontSize: '11px', color: '#64748b', marginTop: '2px' }}>
                      {emp.kana}
                    </div>
                  </td>
                  <td className="td-dept">
                    <span className={getDepartmentClass(emp.department)}>
                      {emp.department}
                    </span>
                  </td>
                  <td className="td-age">{emp.age}歳</td>
                  <td>{emp.role}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default EmployeeTable;

import { useState, useMemo } from 'react';
import { SortKey, SortOrder } from './types';
import { mockEmployees } from './mockData';
import SearchBar from './components/SearchBar';
import EmployeeTable from './components/EmployeeTable';

const App = () => {
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [departmentFilter, setDepartmentFilter] = useState<string>('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const departments = useMemo(() => {
    const set = new Set(mockEmployees.map((e) => e.department));
    return Array.from(set);
  }, []);

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortOrder('asc');
    }
  };

  const handleReset = () => {
    setSearchQuery('');
    setDepartmentFilter('');
    setSortKey('name');
    setSortOrder('asc');
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();

    const filtered = mockEmployees.filter((emp) => {
      const matchSearch =
        query === '' ||
        emp.name.toLowerCase().includes(query) ||
        emp.kana.toLowerCase().includes(query);

      const matchDept =
        departmentFilter === '' || emp.department === departmentFilter;

      return matchSearch && matchDept;
    });

    return filtered.sort((a, b) => {
      let comp = 0;
      if (sortKey === 'name') {
        comp = a.kana.localeCompare(b.kana, 'ja');
      } else if (sortKey === 'department') {
        comp = a.department.localeCompare(b.department, 'ja');
      } else if (sortKey === 'age') {
        comp = a.age - b.age;
      }
      return sortOrder === 'asc' ? comp : -comp;
    });
  }, [searchQuery, departmentFilter, sortKey, sortOrder]);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">社員名簿管理テーブル</h1>
        <p className="app-subtitle">
          社員10名の名簿一覧。列ヘッダーのクリックで昇順・降順ソート、名前検索や部署絞り込みが可能です。
        </p>
      </header>

      <SearchBar
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        departmentFilter={departmentFilter}
        onDepartmentChange={setDepartmentFilter}
        departments={departments}
        onReset={handleReset}
        totalCount={mockEmployees.length}
        matchCount={filteredAndSortedEmployees.length}
      />

      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortKey={sortKey}
        sortOrder={sortOrder}
        onSort={handleSort}
      />

      <footer className="app-footer">
        © 社員名簿管理システム — テーブル見出し（氏名・部署・年齢）をクリックしてソート
      </footer>
    </div>
  );
};

export default App;
